-- Optional future PostgreSQL schema. The v1 static site does not require a database.
create table elections (id bigserial primary key, state_code char(2) not null, election_year integer not null, election_date date not null, ev_start_date date, source_url text not null, unique(state_code,election_year));
create table counties (fips char(5) primary key, state_code char(2) not null, county_name text not null);
create table coverage_sets (id text primary key, description text not null);
create table coverage_members (coverage_id text references coverage_sets(id), county_fips char(5) references counties(fips), primary key(coverage_id,county_fips));
create table report_snapshots (id bigserial primary key, election_id bigint references elections(id), report_date date not null, fetched_at timestamptz not null default now(), source_url text not null, sha256 char(64) not null, parser_version text not null, unique(election_id,report_date,sha256));
create table county_turnout (snapshot_id bigint references report_snapshots(id), county_fips char(5) references counties(fips), ev_day integer, cumulative_in_person bigint, cumulative_mail bigint, cumulative_total bigint not null check(cumulative_total>=0), registered_voters bigint, primary key(snapshot_id,county_fips));
create table state_day_aggregates (election_id bigint references elections(id), coverage_id text references coverage_sets(id), ev_day integer not null, report_date date not null, snapshot_id bigint references report_snapshots(id), cumulative_ballots bigint not null check(cumulative_ballots>=0), registered_voters bigint, approved_at timestamptz, primary key(election_id,coverage_id,ev_day,snapshot_id));
create table party_models (id bigserial primary key, election_id bigint references elections(id), coverage_id text references coverage_sets(id), ev_day integer not null, model_name text not null, model_version text not null, modeled_quantity text not null, dem_share numeric(6,5), rep_share numeric(6,5), independent_share numeric(6,5), uncertainty_json jsonb, methodology_url text not null, license text, created_at timestamptz not null default now());
